async (page) => {
  const { execSync } = require('child_process');
  let output = '';
  output += execSync('chmod +x /tmp/mcp-workspace/workspace/monitor_cpu.sh').toString();
  output += 'Starting script at ' + new Date().toISOString() + '\n';
  output += execSync('bash /tmp/mcp-workspace/workspace/monitor_cpu.sh', { timeout: 120000 }).toString();
  output += 'Finished at ' + new Date().toISOString() + '\n';
  output += '--- LOG FILE CONTENTS ---\n';
  output += execSync('cat /tmp/mcp-workspace/workspace/cpu_monitor.log').toString();
  return output;
}
